import{_ as n,a0 as p,w as g,s as h,I as t,x as s,a1 as e,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"你應該知道的基礎 Git 命令 | LCTT x X-CMD","titleTemplate":false,"description":"你應該知道的基礎 Git 命令 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你應該知道的基礎 Git 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你應該知道的基礎 Git 命令 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160606 Basic Git Commands You Must Know","title":"你應該知道的基礎 Git 命令","tag":"201607","desc":""},"relativePath":"201607/20160606 Basic Git Commands You Must Know.md","filePath":"[post].md"}'),o={name:"201607/20160606 Basic Git Commands You Must Know.md"};function r(k,i,b,u,c,f){const a=p("Link");return g(),h("div",null,[i[21]||(i[21]=t("h1",{id:"你應該知道的基礎-git-命令",tabindex:"-1"},[s("你應該知道的基礎 Git 命令 "),t("a",{class:"header-anchor",href:"#你應該知道的基礎-git-命令","aria-label":"Permalink to “你應該知道的基礎 Git 命令”"},"​")],-1)),i[22]||(i[22]=t("p",null,[t("img",{src:"http://itsfoss.com/wp-content/uploads/2016/06/Download-Git-Sheet.jpg",alt:""})],-1)),i[23]||(i[23]=t("p",null,[t("em",null,"簡介：這個快速指南將向你展示所有的基礎 Git 命令以及用法。你可以下載這些命令作為快速參考。")],-1)),t("p",null,[i[1]||(i[1]=s("我們在早先一篇文章中已經快速介紹過 ",-1)),e(a,{href:"http://itsfoss.com/download-vi-cheat-sheet/"},{default:l(()=>[...i[0]||(i[0]=[s("Vi 速查表",-1)])]),_:1}),i[2]||(i[2]=s("了。在這篇文章裏，我們將會介紹開始使用 Git 時所需要的基礎命令。",-1))]),i[24]||(i[24]=t("h3",{id:"git",tabindex:"-1"},[s("Git "),t("a",{class:"header-anchor",href:"#git","aria-label":"Permalink to “Git”"},"​")],-1)),t("p",null,[e(a,{href:"https://git-scm.com/"},{default:l(()=>[...i[3]||(i[3]=[s("Git",-1)])]),_:1}),i[5]||(i[5]=s(" 是一個分佈式版本控制系統，它被用在大量開源項目中。它是在 2005 年由 Linux 創始人 ",-1)),e(a,{href:"https://en.wikipedia.org/wiki/Linus_Torvalds"},{default:l(()=>[...i[4]||(i[4]=[s("Linus Torvalds",-1)])]),_:1}),i[6]||(i[6]=s(" 寫就的。這個程序允許非線性的項目開發，並且能夠通過存儲在本地服務器高效處理大量數據。在這個教程裏，我們將要和 Git 愉快玩耍並學習如何開始使用它。",-1))]),i[25]||(i[25]=d(`<p>我在這個教程裏使用 Ubuntu，但你可以使用你選擇的任何發行版。除了安裝以外，剩下的所有命令在任何 Linux 發行版上都是一樣的。</p><h3 id="安裝-git" tabindex="-1">安裝 Git <a class="header-anchor" href="#安裝-git" aria-label="Permalink to “安裝 Git”">​</a></h3><p>要安裝 git 執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git-core</span></span></code></pre></div><p>在它完成下載之後，你就安裝好了 Git 並且可以使用了。</p><h3 id="設置-git" tabindex="-1">設置 Git <a class="header-anchor" href="#設置-git" aria-label="Permalink to “設置 Git”">​</a></h3><p>在 Git 安裝之後，不論是從 apt-get 還是從源碼安裝，你需要將你的用户名和郵箱地址複製到 gitconfig 文件。你可以訪問 ~/.gitconfig 這個文件。</p><p>全新安裝 Git 之後打開它會是完全空白的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vim ~/.gitconfig</span></span></code></pre></div><p>你也可以使用以下命令添加所需的信息。將‘user’替換成你的用户名，‘user@example.com’替換成你的郵箱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git config --global user.name &quot;User&quot;</span></span>
<span class="line"><span>git config --global user.email user@example.com</span></span></code></pre></div><p>然後你就完成設置了。現在讓我們開始 Git。</p><h3 id="倉庫" tabindex="-1">倉庫 <a class="header-anchor" href="#倉庫" aria-label="Permalink to “倉庫”">​</a></h3><p>創建一個新目錄，打開它並運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git init</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-git-1-1024x173.png" alt=""></p><p>這個命令會創建一個新的 Git 倉庫（repository）。你的本地倉庫由三個 Git 維護的“樹”組成。</p><p>第一個是你的工作目錄（Working Directory），保存實際的文件。第二個是索引，實際上扮演的是暫存區（staging area），最後一個是 HEAD，它指向你最後一個 commit 提交。使用 git clone /path/to/repository 簽出你的倉庫（從你剛創建的倉庫或服務器上已存在的倉庫）。</p><h3 id="添加文件並提交" tabindex="-1">添加文件並提交 <a class="header-anchor" href="#添加文件並提交" aria-label="Permalink to “添加文件並提交”">​</a></h3><p>你可以用以下命令添加改動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add &lt;filename&gt;</span></span></code></pre></div><p>這會添加一個新文件到暫存區以提交。如果你想添加每個新文件，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add --all</span></span></code></pre></div><p>添加文件之後可以使用以下命令檢查狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git status</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-git-2-1024x219.png" alt=""></p><p>正如你看到的，那裏已經有一些變化但還沒有提交。現在你需要提交這些變化，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m &quot;提交信息&quot;</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/playing-around-git-3-1024x124.png" alt=""></p><p>你也可以這麼做（首選）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -a</span></span></code></pre></div><p>然後寫下你的提交信息。現在你的文件提交到了 HEAD，但還不在你的遠程倉庫中。</p><h3 id="推送你的改動" tabindex="-1">推送你的改動 <a class="header-anchor" href="#推送你的改動" aria-label="Permalink to “推送你的改動”">​</a></h3><p>你的改動在你本地工作副本的 HEAD 中。如果你還沒有從一個已存在的倉庫克隆，或想將你的倉庫連接到遠程服務器，你需要先添加它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git remote add origin &lt;服務器地址&gt;</span></span></code></pre></div><p>現在你可以將改動推送到指定的遠程服務器。要將改動發送到遠程服務器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git push -u origin master</span></span></code></pre></div><h3 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to “分支”">​</a></h3><p>分支用於開發特性，分支之間是互相獨立的。主分支 master 是你創建一個倉庫時的“默認”分支。使用其它分支用於開發，在完成時將它合併回主分支。</p><p>創建一個名為“mybranch”的分支並切換到它之上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git checkout -b mybranch</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-Git-4--1024x145.jpg" alt=""></p><p>你可以使用這個命令切換回主分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git checkout master</span></span></code></pre></div><p>如果你想刪除這個分支，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git branch -d mybranch</span></span></code></pre></div><p><img src="http://itsfoss.com/wp-content/uploads/2016/05/Playing-around-Git-5-1-1024x181.jpg" alt=""></p><p>除非你將分支推送到遠程服務器上，否則該分支對其他人是不可用的，所以只需把它推送上去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git push origin &lt;分支名&gt;</span></span></code></pre></div><h3 id="更新和合並" tabindex="-1">更新和合並 <a class="header-anchor" href="#更新和合並" aria-label="Permalink to “更新和合並”">​</a></h3><p>要將你本地倉庫更新到最新的提交上，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git pull</span></span></code></pre></div><p>在你的工作目錄獲取併合並遠程變動。要合併其它分支到你的活動分支（如 master），使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git merge &lt;分支&gt;</span></span></code></pre></div><p>在這兩種情況下，git 會嘗試自動合併（auto-merge）改動。不幸的是，這不總是可能的，可能會導致衝突。你需要通過編輯 git 所顯示的文件，手動合併那些衝突。改動之後，你需要用以下命令將它們標記為已合併：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add &lt;文件名&gt;</span></span></code></pre></div><p>在合併改動之前，你也可以使用以下命令預覽：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git diff &lt;源分支&gt; &lt;目標分支&gt;</span></span></code></pre></div><h3 id="git-日誌" tabindex="-1">Git 日誌 <a class="header-anchor" href="#git-日誌" aria-label="Permalink to “Git 日誌”">​</a></h3><p>你可以這麼查看倉庫歷史：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log</span></span></code></pre></div><p>要以每個提交一行的樣式查看日誌，你可以用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log --pretty=oneline</span></span></code></pre></div><p>或者也許你想要看一個所有分支的 ASCII 藝術樹，帶有標籤和分支名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log --graph --oneline --decorate --all</span></span></code></pre></div><p>如果你只想看哪些文件改動過：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log --name-status</span></span></code></pre></div><p>在這整個過程中如果你需要任何幫助，你可以用 git --help。</p><p>Git 棒不棒？！祝賀你你已經會 Git 基礎了。如果你願意的話，你可以從下面這個鏈接下載這些基礎 Git 命令作為快速參考：</p>`,69)),t("ul",null,[t("li",null,[e(a,{href:"https://drive.google.com/open?id=0By49_3Av9sT1bXpINjhvU29VNUU"},{default:l(()=>[...i[7]||(i[7]=[s("下載 Git 速查表",-1)])]),_:1})])]),i[26]||(i[26]=t("hr",null,null,-1)),t("p",null,[i[9]||(i[9]=s("via: ",-1)),e(a,{href:"http://itsfoss.com/basic-git-commands-cheat-sheet/"},{default:l(()=>[...i[8]||(i[8]=[s("http://itsfoss.com/basic-git-commands-cheat-sheet/",-1)])]),_:1})]),t("p",null,[i[13]||(i[13]=s("作者：",-1)),e(a,{href:"http://itsfoss.com/author/rakhi/"},{default:l(()=>[...i[10]||(i[10]=[s("Rakhi Sharma",-1)])]),_:1}),i[14]||(i[14]=s(" 譯者：",-1)),e(a,{href:"https://github.com/alim0x"},{default:l(()=>[...i[11]||(i[11]=[s("alim0x",-1)])]),_:1}),i[15]||(i[15]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[12]||(i[12]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[16]||(i[16]=[s("LCTT",-1)])]),_:1}),i[19]||(i[19]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...i[17]||(i[17]=[s("Linux中國",-1)])]),_:1}),i[20]||(i[20]=s(" 榮譽推出",-1))])])}const v=n(o,[["render",r]]);export{C as __pageData,v as default};
